// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function(e) {
    ibx_comAbbrv.focus();
};

scwin.onpageunload = function() {
};

// WebSquare 컴포넌트 이벤트 함수
scwin.ibx_coSnm_onkeydown = function(e) {
    // 기업명 엔터
    if (e.keyCode === 13) {
        scwin.search();
    }
};

scwin.btn_stdIndCd_onclick = function() {
    // 업종검색 팝업 오픈
    scwin.fn_StdIndSrchOpen();
};

scwin.btn_affCoCd_onclick = function() {
    // 기업집단검색 팝업 오픈
    scwin.fn_AffCoCdSrchOpen();
};

scwin.ibx_entprGrpNm_onkeydown = function() {
    // 기업집단검색 팝업 오픈
    if (event.keyCode === 13) {
        scwin.fn_AffCoCdSrchOpen();
    }
};

scwin.img_Search_onclick = function (e) {
    // 조회 버튼 클릭
    scwin.search();
};

scwin.img_Close_onclick = function (e) {
    $c.win.closePopup();
};

scwin.txb_Search_onkeydown = function (e) {
    // 기업명 엔터
    if (e.keyCode === 13) {
        scwin.search();
    }
};

scwin.grd_IsuInst_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    scwin.setParam(rowIndex);
};

// 일반 함수
/**
 *  데이터셋 초기화.
 */
scwin.initDs = function() {
    dataResList.removeAll();
    txb_TotCnt.setValue("0");
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {
    //필수항목 체크.

};

/**
 * 기업목록 조회
 */
scwin.search = function() {
    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 필수 체크.
    if (!scwin.chkValid()) {

    }

    const reqMap = {
        comNm: ibx_comAbbrv.getValue() //기업명
    };
    $c.sbm.execute(sbm_isurList, reqMap);
};

/**
 * 선택된 값을 오프너에 전달한다.
 */
scwin.setParam = async function(v_Currow) {

    if (v_Currow === undefined) {
        v_Currow = dataResList.getRowPosition();
    }


    const res = dataResList.getRowJSON(v_Currow);
    $c.win.closePopup(res);
};

scwin.gform_onload = function() {
};

scwin.sbm_comList_submitdone = function (e) {
    // if (dlt_comListRes.errorMsg) {
    //     alert(dlt_comListRes.errorMsg);
    // } else {
    //     tbx_totCnt.setValue("총 " + rowcount + " 건");
    // }
    dlt_comListRes.setJSON(e.responseJSON.body);
    tbx_totCnt.setValue(dlt_comListRes.getRowCount());
};

scwin.sbm_isurList_submitdone = function (e) {
    dataResList.setJSON(e.responseJSON.body);
    txb_TotCnt.setValue(dataResList.getRowCount());
};
